package com.hrx.recovery;
import java.util.*;import java.time.LocalDate;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/supply-chain/followups") @Validated
public class FollowupController {
 private final JdbcTemplate jdbc;private final ApiSupport api;private final IdempotencyService keys;private final FileService files;
 public FollowupController(JdbcTemplate jdbc,ApiSupport api,IdempotencyService keys,FileService files){this.jdbc=jdbc;this.api=api;this.keys=keys;this.files=files;}
 static final String BASE=" FROM hrx.supply_followup t JOIN hrx.supply_demand d ON d.demand_id=t.demand_id JOIN hrx.business_project p ON p.project_id=d.project_id";
 static final String SELECT="SELECT t.*,d.project_id::text,p.project_code,d.bom_line,d.material_code,d.current_status demand_status,(t.current_status='OPEN' AND t.due_date<current_date) overdue,current_date business_date"+BASE;
 @GetMapping public Map<String,Object> list(@RequestParam(defaultValue="0") @Min(0) @Max(100000) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size,@RequestParam(defaultValue="OPEN") String state,@RequestParam(defaultValue="false") boolean mine,@RequestParam(required=false) UUID demandId){
  String where=" WHERE 1=1";var args=new ArrayList<Object>();switch(state){case "ALL"->{}case "OPEN","DONE","CANCELLED"->{where+=" AND t.current_status=?";args.add(state);}case "OVERDUE"->where+=" AND t.current_status='OPEN' AND t.due_date<current_date";default->throw new IllegalArgumentException("不支持的待办筛选");}if(mine){where+=" AND t.assigned_to=hrx.current_user_id()";}if(demandId!=null){where+=" AND t.demand_id=?";args.add(demandId);}
  Long total=jdbc.queryForObject("SELECT count(*)"+BASE+where,Long.class,args.toArray());args.add(size);args.add(page*size);return Map.of("items",jdbc.queryForList(SELECT+where+" ORDER BY t.due_date,t.created_at,t.task_id LIMIT ? OFFSET ?",args.toArray()),"total",total,"page",page,"size",size);
 }
 @GetMapping("/{id}") public Map<String,Object> get(@PathVariable UUID id){var rows=jdbc.queryForList(SELECT+" WHERE t.task_id=?",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"待办不存在或无权访问");return rows.getFirst();}
 @GetMapping("/{id}/events") public List<Map<String,Object>> events(@PathVariable UUID id){get(id);return jdbc.queryForList("SELECT event_id::text,task_id::text,expected_revision,event_code,note,due_date,previous_due_date,evidence_refs::text,actor_user_id::text,occurred_at FROM hrx.supply_followup_event WHERE task_id=? ORDER BY expected_revision",id);}
 @PostMapping public Map<String,Object> create(@Valid @RequestBody Create req,@RequestHeader("Idempotency-Key") String key){UUID actor=api.actor();return keys.execute(actor,"followup.create",key,req,()->{UUID id=jdbc.queryForObject("SELECT hrx.create_followup(?,?,?)",UUID.class,req.demandId(),req.title(),req.dueDate());api.audit(actor,"followup.create",id,Map.of("demandId",req.demandId().toString()));return Map.of("task_id",id.toString(),"revision",0);});}
 @PostMapping("/{id}/events") public Map<String,Object> append(@PathVariable UUID id,@Valid @RequestBody Event req,@RequestHeader("Idempotency-Key") String key){UUID actor=api.actor();return keys.execute(actor,"followup.event."+id,key,req,()->{var t=get(id);files.requireEvidence((UUID)t.get("demand_id"),req.evidenceRefs());UUID event=jdbc.queryForObject("SELECT hrx.apply_followup_event(?,?,?,?,?,?::jsonb)",UUID.class,id,req.expectedRevision(),req.eventCode(),req.note(),req.dueDate(),api.encode(req.evidenceRefs()));api.audit(actor,"followup."+req.eventCode(),id,Map.of("eventId",event.toString()));return Map.of("event_id",event.toString(),"revision",req.expectedRevision()+1);});}
 public record Create(@NotNull UUID demandId,@NotBlank @Size(min=2,max=240) String title,@NotNull LocalDate dueDate){}
 public record Event(@NotNull @Min(0) Integer expectedRevision,@NotNull @Pattern(regexp="NOTE|RESCHEDULE|COMPLETE|CANCEL") String eventCode,@NotBlank @Size(min=2,max=4000) String note,LocalDate dueDate,@NotNull @Size(max=50) List<@NotNull @Pattern(regexp="hrx-file:[A-Za-z0-9][A-Za-z0-9/_-]{0,500}") String> evidenceRefs){}
}
